namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m)
            return 0m;

        var rate = GetCountryRate(countryCode);
        rate = ApplyAccountRateAdjustment(account, net, rate);
        rate = ApplyHighValueRateCap(net, rate);

        return net * rate;
    }

    private static decimal GetCountryRate(string countryCode)
    {
        return countryCode switch
        {
            "GB" => 0.20m,
            "DE" => 0.19m,
            "FR" => 0.20m,
            "IE" => 0.23m,
            _ => 0.0m
        };
    }

    private static decimal ApplyAccountRateAdjustment(Account account, decimal net, decimal rate)
    {
        if (account.Kind == AccountKind.Government)
            return 0m;

        if (account.Kind == AccountKind.Business && net > 10000m)
            return rate * 0.5m;

        return rate;
    }

    private static decimal ApplyHighValueRateCap(decimal net, decimal rate)
    {
        return rate > 0m && net > 100000m
            ? Math.Min(rate, 0.15m)
            : rate;
    }
}
